import type { RequestEvent } from '@sveltejs/kit';
import { SchoolError } from './types.ts';

// The concrete binding is generated by `wrangler types`; this is the RPC payload boundary.
export function previewClient(event:RequestEvent):any|null{
 const binding=Reflect.get(event.platform?.env??{},'PREVIEW_SCHOOL');
 return binding?binding.getByName('school-v1'):null;
}
export function unwrapPreview<T=any>(result:{ok:boolean;value?:T;status?:number;message?:string}):T{
 if(!result.ok)throw new SchoolError(result.status??500,result.message??'Ошибка preview.');
 return result.value as T;
}
